import { useState } from "react"
import { createRoot } from "react-dom/client"

function Counter({ label }) {
  const [count, setCount] = useState(0)
  return (
    <div className="counter">
      <h3>{label}</h3>
      <p className="count">Plates: {count}</p>
      <button onClick={() => setCount(count + 1)}>Add</button>
      <button onClick={() => setCount(Math.max(0, count - 1))}>Remove</button>
      <button onClick={() => { setCount((c) => c + 1); setCount((c) => c + 1); setCount((c) => c + 1) }}>Add 3</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  )
}

function App() {
  return (
    <>
      <Counter label="Party jollof" />
      <Counter label="Pepper soup" />
    </>
  )
}

createRoot(document.getElementById("root")).render(<App />)
